import{_ as e,o as r,c as a,a3 as n}from"./chunks/framework.BL7OzMv1.js";const p=JSON.parse(`{"title":"Grille d'évaluation — Examen 2","description":"","frontmatter":{"title":"Grille d'évaluation — Examen 2"},"headers":[],"relativePath":"grilles/grille-examen2.md","filePath":"grilles/grille-examen2.md"}`),o={name:"grilles/grille-examen2.md"};function i(s,t,d,c,l,u){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="grille-d-evaluation-—-examen-2" tabindex="-1">Grille d&#39;évaluation — Examen 2 <a class="header-anchor" href="#grille-d-evaluation-—-examen-2" aria-label="Permalink to &quot;Grille d&#39;évaluation — Examen 2&quot;">​</a></h1><h2 id="echelle-d-evaluation" tabindex="-1">Échelle d&#39;évaluation <a class="header-anchor" href="#echelle-d-evaluation" aria-label="Permalink to &quot;Échelle d&#39;évaluation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Niveau</th><th>Valeur</th></tr></thead><tbody><tr><td>Excellent</td><td>100 %</td></tr><tr><td>Suffisant</td><td>70 %</td></tr><tr><td>Insuffisant</td><td>40 %</td></tr><tr><td>Incorrect</td><td>0 %</td></tr></tbody></table><h2 id="penalites" tabindex="-1">Pénalités <a class="header-anchor" href="#penalites" aria-label="Permalink to &quot;Pénalités&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Pénalité</th><th>Facteur</th><th>Maximum</th></tr></thead><tbody><tr><td>Retard (par jour)</td><td>−10 %</td><td>−30 %</td></tr><tr><td>Notion non vue au cours</td><td>−5 % / occurrence</td><td>−30 %</td></tr></tbody></table><hr><h2 id="partie-1-—-revision-des-acquis-30" tabindex="-1">Partie 1 — Révision des acquis (30 %) <a class="header-anchor" href="#partie-1-—-revision-des-acquis-30" aria-label="Permalink to &quot;Partie 1 — Révision des acquis (30 %)&quot;">​</a></h2><h3 id="q1-—-debogage-de-requete-sql-6-pts" tabindex="-1">Q1 — Débogage de requête SQL (6 pts) <a class="header-anchor" href="#q1-—-debogage-de-requete-sql-6-pts" aria-label="Permalink to &quot;Q1 — Débogage de requête SQL (6 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Erreur identifiée avec précision. Requête corrigée valide et complète.</td></tr><tr><td>Suffisant</td><td>Erreur identifiée correctement mais correction incomplète, ou correction juste mais explication vague.</td></tr><tr><td>Insuffisant</td><td>Erreur vaguement identifiée ou correction tentée mais toujours incorrecte.</td></tr><tr><td>Incorrect</td><td>Aucune identification de l&#39;erreur et aucune correction fonctionnelle.</td></tr></tbody></table><hr><h3 id="q2-—-debogage-de-requete-sql-6-pts" tabindex="-1">Q2 — Débogage de requête SQL (6 pts) <a class="header-anchor" href="#q2-—-debogage-de-requete-sql-6-pts" aria-label="Permalink to &quot;Q2 — Débogage de requête SQL (6 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Erreur identifiée avec précision. Requête corrigée valide et complète.</td></tr><tr><td>Suffisant</td><td>Erreur identifiée correctement mais correction incomplète, ou correction juste mais explication vague.</td></tr><tr><td>Insuffisant</td><td>Erreur vaguement identifiée ou correction tentée mais toujours incorrecte.</td></tr><tr><td>Incorrect</td><td>Aucune identification de l&#39;erreur et aucune correction fonctionnelle.</td></tr></tbody></table><hr><h3 id="q3-—-insert-4-pts" tabindex="-1">Q3 — INSERT (4 pts) <a class="header-anchor" href="#q3-—-insert-4-pts" aria-label="Permalink to &quot;Q3 — INSERT (4 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>2 insertions valides. Toutes les colonnes listées explicitement. Valeurs conformes à l&#39;énoncé.</td></tr><tr><td>Suffisant</td><td>1 insertion valide et complète, ou les 2 tentées avec colonnes explicites mais une valeur erronée.</td></tr><tr><td>Insuffisant</td><td>Les 2 insertions tentées mais colonnes omises ou plusieurs valeurs incorrectes.</td></tr><tr><td>Incorrect</td><td>Aucune insertion fonctionnelle.</td></tr></tbody></table><hr><h3 id="q4-—-update-6-pts" tabindex="-1">Q4 — UPDATE (6 pts) <a class="header-anchor" href="#q4-—-update-6-pts" aria-label="Permalink to &quot;Q4 — UPDATE (6 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Les deux conditions de filtre présentes et correctes. Colonne mise à jour conforme.</td></tr><tr><td>Suffisant</td><td>Une seule des deux conditions présente, ou colonne mise à jour incorrecte mais logique générale juste.</td></tr><tr><td>Insuffisant</td><td>Structure <code>UPDATE … SET … WHERE</code> présente mais logique de filtre majoritairement incorrecte.</td></tr><tr><td>Incorrect</td><td>Non fonctionnel ou logique absente.</td></tr></tbody></table><hr><h3 id="q5-—-delete-avec-sous-requete-non-correlee-8-pts" tabindex="-1">Q5 — DELETE avec sous-requête non corrélée (8 pts) <a class="header-anchor" href="#q5-—-delete-avec-sous-requete-non-correlee-8-pts" aria-label="Permalink to &quot;Q5 — DELETE avec sous-requête non corrélée (8 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td><code>DELETE</code> correct. Sous-requête non corrélée explicite. Lignes correctes supprimées.</td></tr><tr><td>Suffisant</td><td>Logique correcte et lignes correctes supprimées, mais sous-requête corrélée utilisée à la place.</td></tr><tr><td>Insuffisant</td><td><code>DELETE</code> avec tentative de sous-requête présente mais ciblant les mauvaises lignes, car la clé de lisaison est incorrecte</td></tr><tr><td>Incorrect</td><td>Non fonctionnel ou aucune tentative cohérente.</td></tr></tbody></table><hr><h2 id="partie-2-—-jointures-agregations-et-sous-requetes-35" tabindex="-1">Partie 2 — Jointures, agrégations et sous-requêtes (35 %) <a class="header-anchor" href="#partie-2-—-jointures-agregations-et-sous-requetes-35" aria-label="Permalink to &quot;Partie 2 — Jointures, agrégations et sous-requêtes (35 %)&quot;">​</a></h2><h3 id="q6-—-filtre-avec-expression-reguliere-5-pts" tabindex="-1">Q6 — Filtre avec expression régulière (5 pts) <a class="header-anchor" href="#q6-—-filtre-avec-expression-reguliere-5-pts" aria-label="Permalink to &quot;Q6 — Filtre avec expression régulière (5 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Pattern regex exact. Colonnes demandées et tri conformes à l&#39;énoncé.</td></tr><tr><td>Suffisant</td><td>Requête fonctionnelle mais pattern légèrement imprécis (ex. : ancres manquantes) ou tri absent.</td></tr><tr><td>Insuffisant</td><td>Regex utilisée mais pattern significativement erroné (la majorité des cas ne sont pas couverts).</td></tr><tr><td>Incorrect</td><td>Pas d&#39;expression régulière ou requête non fonctionnelle.</td></tr></tbody></table><hr><h3 id="q7-—-jointure-interne-6-pts" tabindex="-1">Q7 — Jointure interne (6 pts) <a class="header-anchor" href="#q7-—-jointure-interne-6-pts" aria-label="Permalink to &quot;Q7 — Jointure interne (6 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Jointure correcte. Filtre appliqué correctement. Colonnes demandées et tri conformes à l&#39;énoncé.</td></tr><tr><td>Suffisant</td><td>Jointure fonctionnelle mais filtre absent, colonne manquante ou tri incorrect.</td></tr><tr><td>Insuffisant</td><td>Jointure tentée mais mauvais type de jointure ou condition de jointure incorrecte.</td></tr><tr><td>Incorrect</td><td>Non fonctionnelle ou aucune jointure présente.</td></tr></tbody></table><hr><h3 id="q8-—-jointure-externe-6-pts" tabindex="-1">Q8 — Jointure externe (6 pts) <a class="header-anchor" href="#q8-—-jointure-externe-6-pts" aria-label="Permalink to &quot;Q8 — Jointure externe (6 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Jointure externe correcte. Tous les enregistrements de la table principale conservés. Colonnes et tri conformes à l&#39;énoncé.</td></tr><tr><td>Suffisant</td><td>Jointure fonctionnelle mais mauvais sens de jointure ou jointure interne utilisée (lignes sans correspondance perdues), ou tri incorrect.</td></tr><tr><td>Insuffisant</td><td>Jointure tentée mais mauvais type de jointure ou condition de jointure incorrecte.</td></tr><tr><td>Incorrect</td><td>Non fonctionnelle ou aucune jointure présente.</td></tr></tbody></table><hr><h3 id="q9-—-agregation-et-group-by-8-pts" tabindex="-1">Q9 — Agrégation et GROUP BY (8 pts) <a class="header-anchor" href="#q9-—-agregation-et-group-by-8-pts" aria-label="Permalink to &quot;Q9 — Agrégation et GROUP BY (8 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td><code>GROUP BY</code> correct. Fonctions d&#39;agrégation correctes. Tri décroissant par nombre.</td></tr><tr><td>Suffisant</td><td>Fonctionnelle mais alias manquants ou tri incorrect.</td></tr><tr><td>Insuffisant</td><td><code>GROUP BY</code> présent mais mauvaise colonne de regroupement ou mauvaise fonction d&#39;agrégation ou une fonction manquante.</td></tr><tr><td>Incorrect</td><td>Non fonctionnelle ou regroupement absent.</td></tr></tbody></table><hr><h3 id="q10-—-group-by-et-having-5-pts" tabindex="-1">Q10 — GROUP BY et HAVING (5 pts) <a class="header-anchor" href="#q10-—-group-by-et-having-5-pts" aria-label="Permalink to &quot;Q10 — GROUP BY et HAVING (5 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td><code>GROUP BY</code> correct. Filtre <code>HAVING</code> appliqué sur le bon seuil. Colonnes conformes.</td></tr><tr><td>Suffisant</td><td>Fonctionnelle mais seuil incorrect dans <code>HAVING</code></td></tr><tr><td>Insuffisant</td><td><code>GROUP BY</code> présent mais <code>HAVING</code> absent ou filtre <code>WHERE</code> absent.</td></tr><tr><td>Incorrect</td><td>Non fonctionnelle ou logique de regroupement absente.</td></tr></tbody></table><hr><h3 id="q11-—-sous-requete-correlee-5-pts" tabindex="-1">Q11 — Sous-requête corrélée (5 pts) <a class="header-anchor" href="#q11-—-sous-requete-correlee-5-pts" aria-label="Permalink to &quot;Q11 — Sous-requête corrélée (5 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Sous-requête corrélée explicite. Référence à la table externe correcte. Résultats corrects.</td></tr><tr><td>Suffisant</td><td>Logique correcte mais sous-requête non corrélée (moyenne globale au lieu de la moyenne par groupe).</td></tr><tr><td>Insuffisant</td><td>Sous-requête tentée mais ne compare pas la cotisation à la moyenne du bon groupe.</td></tr><tr><td>Incorrect</td><td>Non fonctionnelle ou aucune sous-requête présente.</td></tr></tbody></table><hr><h2 id="partie-3-—-ddl-avance-securite-et-mots-de-passe-35" tabindex="-1">Partie 3 — DDL avancé, sécurité et mots de passe (35 %) <a class="header-anchor" href="#partie-3-—-ddl-avance-securite-et-mots-de-passe-35" aria-label="Permalink to &quot;Partie 3 — DDL avancé, sécurité et mots de passe (35 %)&quot;">​</a></h2><h3 id="q12-—-alter-table-—-ajout-de-contraintes-6-pts" tabindex="-1">Q12 — ALTER TABLE — Ajout de contraintes (6 pts) <a class="header-anchor" href="#q12-—-alter-table-—-ajout-de-contraintes-6-pts" aria-label="Permalink to &quot;Q12 — ALTER TABLE — Ajout de contraintes (6 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Les deux contraintes ajoutées avec les noms exacts fournis dans l&#39;énoncé. Pattern regex correct et fonctionnel.</td></tr><tr><td>Suffisant</td><td>Une contrainte correcte et complète ; l&#39;autre absente ou utilisation d&#39;un nom inexact.</td></tr><tr><td>Insuffisant</td><td>Les deux contraintes tentées mais noms incorrects et/ou pattern regex significativement erroné.</td></tr><tr><td>Incorrect</td><td>Non fonctionnel ou aucune contrainte ajoutée.</td></tr></tbody></table><hr><h3 id="q13-—-alter-table-—-suppression-en-cascade-7-pts" tabindex="-1">Q13 — ALTER TABLE — Suppression en cascade (7 pts) <a class="header-anchor" href="#q13-—-alter-table-—-suppression-en-cascade-7-pts" aria-label="Permalink to &quot;Q13 — ALTER TABLE — Suppression en cascade (7 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Ancienne contrainte supprimée. Nouvelle contrainte ajoutée avec <code>ON DELETE CASCADE</code> et le nom exact fourni dans l&#39;énoncé. La clé étrangère référence la bonne table.</td></tr><tr><td>Suffisant</td><td><code>ON DELETE CASCADE</code> correct mais nom de la nouvelle contrainte inexact, ou les deux étapes présentes mais dans le mauvais ordre ou la clé étrangère référence la mauvaise table.</td></tr><tr><td>Insuffisant</td><td>Une seule des deux étapes réalisée (suppression sans recréation, ou recréation sans suppression préalable).</td></tr><tr><td>Incorrect</td><td>Non fonctionnel ou contrainte incorrecte.</td></tr></tbody></table><hr><h3 id="q14-—-hachage-des-mots-de-passe-pgcrypto-10-pts" tabindex="-1">Q14 — Hachage des mots de passe (pgcrypto) (10 pts) <a class="header-anchor" href="#q14-—-hachage-des-mots-de-passe-pgcrypto-10-pts" aria-label="Permalink to &quot;Q14 — Hachage des mots de passe (pgcrypto) (10 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Les 4 étapes réalisées dans l&#39;ordre. Extension activée. Colonne hachée ajoutée. <code>UPDATE</code> avec <code>crypt(…, gen_salt(&#39;bf&#39;))</code>. Colonne en clair supprimée.</td></tr><tr><td>Suffisant</td><td>3 étapes correctes ; une étape manquante (ex. : colonne en clair non supprimée, ou extension absente mais hachage fonctionnel).</td></tr><tr><td>Insuffisant</td><td>Seulement 1 ou 2 étapes réalisées correctement ; hachage tenté mais paramètres incorrects.</td></tr><tr><td>Incorrect</td><td>Hachage absent ou migration non fonctionnelle.</td></tr></tbody></table><hr><h3 id="q15-—-roles-utilisateurs-et-privileges-12-pts" tabindex="-1">Q15 — Rôles, utilisateurs et privilèges (12 pts) <a class="header-anchor" href="#q15-—-roles-utilisateurs-et-privileges-12-pts" aria-label="Permalink to &quot;Q15 — Rôles, utilisateurs et privilèges (12 pts)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Niveau</th><th>Description</th></tr></thead><tbody><tr><td>Excellent</td><td>Rôles et utilisateurs créés. Associations utilisateur–rôle correctes. <code>SELECT</code> accordé sur toutes les tables au rôle lecture. <code>ALL PRIVILEGES</code> accordé sur toutes les tables <strong>et séquences</strong> au rôle admin. <code>REVOKE SELECT</code> appliqué sur la table sensible.</td></tr><tr><td>Suffisant</td><td>Fonctionnel mais un élément manquant ou mal ciblé : séquences oubliées, <code>REVOKE</code> absent, ou une association utilisateur–rôle incorrecte.</td></tr><tr><td>Insuffisant</td><td>Rôles ou utilisateurs créés partiellement ; privilèges incomplets ou la moitié des éléments manquants.</td></tr><tr><td>Incorrect</td><td>Non fonctionnel ou privilèges majoritairement incorrects.</td></tr></tbody></table>',53)])])}const b=e(o,[["render",i]]);export{p as __pageData,b as default};
